            } catch (e2) {
                console.warn('  ⚠️  gh-848 belt: concluding check-run ' +
                             cr.id + ' failed: ' + (e2.message || e2));
            }
        });
    } finally {
        if (swapped && sourceTok) {
            try { set_env_variable('GH_TOKEN', sourceTok); } catch (e3) {}
        }
    }
