            set_env_variable('GH_TOKEN', appToken);
            swapped = true;
        } catch (eSwap) {
            console.warn('  ⚠️  gh-848 token swap failed, belt uses the PAT ' +
                         '(will 403): ' + (eSwap.message || eSwap));
