function cloneRan(cmds) {
    return cmds.some(function (c) { return c.command.indexOf('gh repo clone') !== -1; });
}
function mockPrPayload(gh, cmds) {
    if (gh.prAfterRefresh && cloneRan(cmds)) return gh.prAfterRefresh;
