            return JSON.stringify({ workflow_runs: byStatus[status] || [] });
        },
        getRemoteRepoInfo: function() { return null; }
    };
    var mockScmModule = {
        createScm: function(config) { capturedScmConfigs.push(config); return mockScmProvider; }
