            var m = /^([0-9a-f]{40})/.exec(tail.trim());
            if (m) sha = m[1];
        });
        return sha;
    } catch (e) {
        console.warn('  ⚠️  park-head probe failed: ' + (e.message || e));
        return null;
    }
