// escalation (or any head-moving push) lifts this park with zero new
// machinery (AC4).
var WORKFLOW_WRITE_PARK_RE =
    /\uD83D\uDD10 workflow-write park \(gh-1106\) [^\n]*parked-head: ([0-9a-f]{7,40})/g;

