            'fatal: token ' + TOK + ' leaked in hook output\n' +
            'and a fine-grained ' + PAT + ' too\n');
        assert.ok(scrubbed.indexOf(TOK) === -1, 'the raw token is gone');
        assert.ok(scrubbed.indexOf(PAT) === -1, 'the fine-grained PAT is gone');
